// src/pages/Dashboard.jsx
import { useNavigate } from "react-router-dom";
import { 
  Utensils, 
  Table, 
  ShoppingCart, 
  Package, 
  Users, 
  LogOut,
  Clock,
  Calendar
} from "lucide-react";
import "./Dashboard.css";

export default function Dashboard() {
  const navigate = useNavigate();

  const cerrarSesion = () => {
    localStorage.removeItem("access_token");
    localStorage.removeItem("refresh_token");
    navigate("/login");
  };

  const menu = [
    {
      titulo: "Mesas",
      subtitulo: "Control de ocupación",
      icon: Table,
      color: "#e74c3c",
      ruta: "/mesas"
    },
    {
      titulo: "Pedidos",
      subtitulo: "Gestión y seguimiento",
      icon: ShoppingCart,
      color: "#c0392b",
      ruta: "/pedidos"
    },
    {
      titulo: "Productos",
      subtitulo: "Menú del restaurante",
      icon: Utensils,
      color: "#e74c3c",
      ruta: "/productos"
    },
    {
      titulo: "Categorías",
      subtitulo: "Organización del menú",
      icon: Package,
      color: "#c0392b",
      ruta: "/categorias"
    },
    {
      titulo: "Empleados",
      subtitulo: "Gestión del personal",
      icon: Users,
      color: "#e74c3c",
      ruta: "/empleados"
    },
    {
      titulo: "Reportes",
      subtitulo: "Ventas y estadísticas",
      icon: Calendar,
      color: "#c0392b",
      ruta: "/reportes"
    }
  ];

  return (
    <div className="dashboard">
      <div className="dashboard-bg"></div>
      <div className="dashboard-overlay"></div>

      <div className="dashboard-content">
        {/* Título */}
        <div className="header">
          <h1 className="title">SOFTFOOD</h1>
          <p className="subtitle">Panel de Control del Restaurante</p>
        </div>

        {/* Grid de tarjetas clicables */}
        <div className="grid">
          {menu.map((item, index) => {
            const Icon = item.icon;
            return (
              <div
                key={index}
                className="card"
                onClick={() => navigate(item.ruta)}
                style={{ "--card-color": item.color }}
              >
                <div className="bg-gradient-to-br from-red-800 to-red-950 rounded-3xl p-10 shadow-2xl hover:shadow-red-900/50 transition-all transform hover:scale-105 cursor-pointer border-4 border-red-500"
     onClick={() => window.open("/cocina", "_blank")}>
  <div className="text-orange-400 text-8xl mb-6">FIRE</div>
  <h2 className="text-4xl font-bold text-white mb-2">COCINA EN VIVO</h2>
  <p className="text-red-200 text-lg">Pantalla roja en tiempo real</p>
</div>
                <div className="card-icon">
                  <Icon size={48} strokeWidth={1.8} />
                </div>
                <h3>{item.titulo}</h3>
                <p>{item.subtitulo}</p>
              </div>
            );
          })}
        </div>

        {/* Botón cerrar sesión */}
        <button onClick={cerrarSesion} className="logout-btn">
          <LogOut size={20} />
          Cerrar Sesión
        </button>
      </div>
    </div>
  );
}
